:root {
  color-scheme: light;
  --ink: #182329;
  --muted: #68777a;
  --paper: #fffdf7;
  --line: #e7e9df;
  --mint: #bde8cf;
  --coral: #f2a18b;
  --yellow: #f2cc68;
  font-family: ui-rounded, "Trebuchet MS", system-ui, sans-serif;
  font-size: 16px;
}
* { box-sizing: border-box; }
body { min-height: 100vh; margin: 0; padding: 40px 16px; display: grid; place-items: center; color: var(--ink); background-color: #eaf1e6; background-image: radial-gradient(#c9dac7 1.2px, transparent 1.2px); background-size: 20px 20px; }
.board { width: min(100%, 620px); padding: 34px; background: var(--paper); border: 2px solid var(--ink); border-radius: 18px; box-shadow: 8px 8px 0 var(--ink); }
.heading { margin-bottom: 26px; }
.eyebrow { margin: 0 0 8px; color: #527565; font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.5rem); line-height: 1.1; letter-spacing: -.045em; }
.sparkle { display: inline-block; margin-left: 9px; color: #dc815f; font-size: .72em; vertical-align: top; }
.intro { margin: 10px 0 0; color: var(--muted); }
.add-form { display: grid; grid-template-columns: minmax(0, 1fr) 130px 52px; align-items: end; gap: 12px; padding: 16px; background: #f3f5ed; border: 1px solid var(--line); border-radius: 12px; }
.field { min-width: 0; }
.field label, .tip-input { display: block; font-size: .9rem; font-weight: 700; }
.field label { margin-bottom: 6px; }
input { min-width: 0; width: 100%; min-height: 46px; padding: 10px 12px; color: var(--ink); font: inherit; background: white; border: 1.5px solid #c9d1c8; border-radius: 8px; }
input:focus-visible, button:focus-visible { outline: 3px solid #487c65; outline-offset: 3px; }
.price-input { position: relative; }
.price-input > span { position: absolute; top: 50%; left: 12px; color: var(--muted); transform: translateY(-50%); }
.price-input input { padding-left: 28px; }
button { min-height: 46px; color: var(--ink); font: inherit; font-weight: 800; cursor: pointer; border: 1.5px solid var(--ink); border-radius: 8px; transition: transform .12s, box-shadow .12s, background-color .12s; }
button:hover { transform: translateY(-2px); box-shadow: 0 3px 0 var(--ink); }
button:active { transform: translateY(1px); box-shadow: none; }
.add-button { background: var(--mint); font-size: 1.6rem; line-height: 1; }
.items-section { margin-top: 28px; }
.section-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
h2 { margin: 0; font-size: 1.08rem; }
.count, .total-label { color: var(--muted); font-size: .78rem; font-weight: 800; letter-spacing: .07em; }
.item-list { display: grid; gap: 10px; margin: 14px 0 0; padding: 0; list-style: none; }
.item-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 12px 13px; border: 1px solid var(--line); border-radius: 10px; }
.item-info { min-width: 0; }
.item-name { overflow-wrap: anywhere; font-weight: 700; }
.item-price { margin-top: 4px; color: var(--muted); font-size: .92rem; }
.sharer-list { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 6px; }
.person-toggle { min-height: 36px; padding: 6px 9px; background: white; font-size: .82rem; }
.person-toggle[aria-pressed="true"] { background: var(--mint); }
.remove-button { min-height: 36px; padding: 5px 9px; background: white; color: #8a4940; font-size: .82rem; }
.empty-state { margin: 14px 0 0; padding: 20px 12px; color: var(--muted); text-align: center; border: 1px dashed #cbd4c9; border-radius: 10px; }
.tip-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-top: 26px; padding: 16px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.tip-row p { margin: 5px 0 0; color: var(--muted); font-size: .88rem; }
.tip-input { display: flex; align-items: center; gap: 8px; }
.tip-input input { width: 82px; min-height: 42px; text-align: right; }
.totals-section { margin-top: 24px; }
.people-totals { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; margin-top: 14px; }
.person-total { padding: 14px; background: #f3f5ed; border: 1px solid var(--line); border-radius: 10px; }
.person-total:nth-child(2) { background: #fff4e9; }
.person-total:nth-child(3) { background: #fdf4e0; }
.person-name { color: var(--muted); font-size: .88rem; font-weight: 700; }
.person-amount { margin-top: 6px; font-size: clamp(1.05rem, 4vw, 1.35rem); font-weight: 850; letter-spacing: -.03em; }
.bill-total { display: flex; justify-content: space-between; align-items: center; margin-top: 16px; padding-top: 14px; border-top: 1px dashed #cbd4c9; }
.bill-total span { font-weight: 700; }
.bill-total strong { font-size: 1.3rem; }
footer { display: flex; justify-content: center; align-items: center; gap: 8px; margin-top: 24px; color: var(--muted); font-size: .85rem; }
.pixel-dot { width: 10px; height: 10px; background: var(--coral); box-shadow: 3px 0 var(--coral), 0 3px var(--coral), 3px 3px var(--coral); }
@media (max-width: 480px) {
  body { padding: 20px 13px; }
  .board { padding: 24px 18px; box-shadow: 5px 5px 0 var(--ink); }
  .add-form { grid-template-columns: minmax(0, 1fr) 52px; gap: 10px; padding: 13px; }
  .item-name-field { grid-column: 1 / -1; }
  .price-field { grid-column: 1; }
  .add-button { grid-column: 2; grid-row: 2; }
  .item-row { grid-template-columns: 1fr; }
  .sharer-list { justify-content: flex-start; }
  .person-total { padding: 11px 9px; }
}

const people = ["Alex", "Blair", "Casey"];
const items = [];
const form = document.querySelector("#item-form");
const itemList = document.querySelector("#item-list");
const emptyState = document.querySelector("#empty-state");
const tipInput = document.querySelector("#tip-percent");
const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

function render() {
  itemList.replaceChildren();
  emptyState.hidden = items.length > 0;
  document.querySelector("#item-count").textContent = `${items.length} ${items.length === 1 ? "item" : "items"}`;

  items.forEach((item, index) => {
    const row = document.createElement("li");
    row.className = "item-row";
    const info = document.createElement("div");
    info.className = "item-info";
    const name = document.createElement("div");
    name.className = "item-name";
    name.textContent = item.name;
    const price = document.createElement("div");
    price.className = "item-price";
    price.textContent = money.format(item.cents / 100);
    info.append(name, price);

    const controls = document.createElement("div");
    controls.className = "sharer-list";
    people.forEach((person, personIndex) => {
      const toggle = document.createElement("button");
      toggle.type = "button";
      toggle.className = "person-toggle";
      toggle.textContent = person;
      toggle.setAttribute("aria-label", `${person} shared ${item.name}`);
      toggle.setAttribute("aria-pressed", String(item.shared[personIndex]));
      toggle.addEventListener("click", () => {
        item.shared[personIndex] = !item.shared[personIndex];
        render();
      });
      controls.append(toggle);
    });
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "remove-button";
    remove.textContent = "Remove";
    remove.setAttribute("aria-label", `Remove ${item.name}`);
    remove.addEventListener("click", () => {
      items.splice(index, 1);
      render();
    });
    controls.append(remove);
    row.append(info, controls);
    itemList.append(row);
  });

  const tipPercent = Math.min(100, Math.max(0, Number(tipInput.value) || 0));
  const totals = people.map(() => 0);
  for (const item of items) {
    const sharers = item.shared.reduce((sum, shared) => sum + Number(shared), 0);
    if (!sharers) continue;
    const shares = [];
    let allocated = 0;
    item.shared.forEach((shared, personIndex) => {
      if (!shared) return;
      const share = Math.floor(item.cents / sharers);
      shares.push([personIndex, share]);
      allocated += share;
    });
    let remainder = item.cents - allocated;
    for (const [personIndex, share] of shares) {
      const cents = share + (remainder-- > 0 ? 1 : 0);
      const tippedCents = Math.round(cents * (1 + tipPercent / 100));
      totals[personIndex] += tippedCents;
    }
  }
  document.querySelector("#people-totals").replaceChildren(...totals.map((cents, index) => {
    const card = document.createElement("div");
    card.className = "person-total";
    const label = document.createElement("div");
    label.className = "person-name";
    label.textContent = people[index];
    const amount = document.createElement("div");
    amount.className = "person-amount";
    amount.textContent = money.format(cents / 100);
    card.append(label, amount);
    return card;
  }));
  document.querySelector("#bill-total").textContent = money.format(totals.reduce((sum, cents) => sum + cents, 0) / 100);
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  const nameInput = document.querySelector("#item-name");
  const priceInput = document.querySelector("#item-price");
  const cents = Math.round(Number(priceInput.value) * 100);
  if (!nameInput.value.trim() || !Number.isFinite(cents) || cents < 1) return;
  items.push({ name: nameInput.value.trim(), cents, shared: [false, false, false] });
  form.reset();
  nameInput.focus();
  render();
});
tipInput.addEventListener("input", render);
render();
